class _RuntimeStub:
    def __init__(self, store: ChatStore) -> None:
        self.store = store
        self.state = AppState()
        self.chat_session = ChatSession(session_id="s1")
        self.chat_session.attach_store(store, load_existing=False)
        self.cancelled_runner_tasks: list[str] = []

    def cancel_task_runner_task(self, task_id: str) -> bool:
        self.cancelled_runner_tasks.append(task_id)
        return True

    def switch_session(self, session_id: str) -> None:
        self.chat_session = ChatSession(session_id=session_id)
        self.chat_session.attach_store(
            self.store,
            load_existing=True,
            fail_active_messages=False,
        )

    def start_new_session(self) -> str:
        self.chat_session = ChatSession()
        self.chat_session.attach_store(self.store, load_existing=False)
        return self.chat_session.session_id


def _make_api(tmp_path):
    store = ChatStore(db_path=str(tmp_path / "chat.db"))
    runtime = _RuntimeStub(store)
    return ChatAPI(runtime), runtime, store


def _send_foreground_message(
    api: ChatAPI,
    *args: Any,
    **kwargs: Any,
) -> dict[str, Any]:
    """Make legacy foreground desktop test authorization explicit."""

    metadata = dict(kwargs.pop("metadata", {}) or {})
    if not any(
        key in metadata
        for key in (
            "allow_user_foreground_takeover",
            "avoid_user_foreground_takeover",
            "desktop_execution_policy",
        )
    ):
        metadata["allow_user_foreground_takeover"] = True
    return api.send_message(*args, metadata=metadata, **kwargs)


def _make_agent_runtime_service(tmp_path) -> AgentRuntimeService:
    return AgentRuntimeService(
        db_path=tmp_path / "agent-runtime.db",
        workspace_dir=tmp_path / "agent-runtime",
        credential_store=MemoryCredentialStore(),
        seed_templates=False,
    )


def _native_postcondition_result(
    result: dict[str, Any],
    *,
    observed_state: str = "",
) -> dict[str, Any]:
    """Return a fake Broker result carrying a production-shaped receipt.

    Successful dispatch alone is intentionally insufficient for an effectful
    GoalContract.  Integration fakes that stand in for a Broker read-after-
    write result must therefore say which postcondition they observed instead
    of relying on ``ok: true`` as implicit completion evidence.
    """

    payload = dict(result)
    data = dict(payload.get("data") or {})
    payload["postcondition_verified"] = True
    data["postcondition_verified"] = True
    if observed_state:
        payload["state"] = observed_state
        payload["verified_observed_state"] = observed_state
        data["state"] = observed_state
        data["verified_observed_state"] = observed_state
    payload["data"] = data
    return payload


def _seed_durable_main_chat_run_without_app_task(
    runtime: _RuntimeStub,
    service: AgentRuntimeService,
    *,
    task_id: str,
    user_goal: str,
) -> dict[str, Any]:
    runtime.agent_runtime_service = service
    user_message_id = runtime.chat_session.add_user_message(user_goal)
    runtime.chat_session.link_message_to_task(user_message_id, task_id)
    runtime.chat_session.upsert_assistant_message(
        task_id,
        "",
        MessageStatus.PROCESSING,
    )
    run = service.start_main_chat_run(
        task_id=task_id,
        session_id=runtime.chat_session.session_id,
        user_goal=user_goal,
    )
    assert runtime.state.get_task(task_id) is None
    return run


def test_chat_api_direct_daily_desktop_task_forwards_runtime_execution_envelope(
    tmp_path,
    monkeypatch,
):
    api, runtime, store = _make_api(tmp_path)
    runtime.agent_runtime_service = object()
    captured: dict[str, Any] = {}

    class FakeStarter:
        def __init__(self, app_runtime, service):
            captured["app_runtime"] = app_runtime
            captured["service"] = service

        def execute_existing_main_chat_task(
            self,
            *,
            task_id,
            conversation_id,
            prompt,
            metadata=None,
            runtime_execution_envelope=None,
            direct_tool_requests=None,
        ):
            captured["task_id"] = task_id
            captured["conversation_id"] = conversation_id
            captured["prompt"] = prompt
            captured["metadata"] = metadata
            captured["runtime_execution_envelope"] = runtime_execution_envelope
            captured["direct_tool_requests"] = direct_tool_requests
            return {
                "task_id": task_id,
                "conversation_id": conversation_id,
                "status": "completed",
                "summary": "done",
                "timeline": [],
            }

    monkeypatch.setattr(
        "apps.shell.yachiyo_agent.legacy_ports.LegacyChatTaskStarter",
        FakeStarter,
    )
    envelope = {
        "envelope_id": "envelope-chat",
        "requests": [{"tool_name": "app.open", "input": {"app_name": "Music"}}],
    }
    direct_requests = [{"tool": "app.open", "input": {"app_name": "Music"}}]

    try:
        result = api._execute_direct_daily_desktop_task(
            task_id="task-chat",
            prompt="打开 Music",
            metadata={"source": "chat_window"},
            runtime_execution_envelope=envelope,
            direct_tool_requests=direct_requests,
        )

        assert result is not None
        assert captured["runtime_execution_envelope"] == envelope
        assert captured["direct_tool_requests"] == direct_requests
        assert captured["metadata"] == {"source": "chat_window"}
        assert captured["conversation_id"] == runtime.chat_session.session_id
    finally:
        store.close()


