def test_send_message_executes_natural_calendar_event_without_model(tmp_path, monkeypatch):
    api, runtime, store = _make_api(tmp_path)
    service = _make_agent_runtime_service(tmp_path)
    runtime.agent_runtime_service = service
    tomorrow = date.today() + timedelta(days=1)
    tomorrow_1000 = f"{tomorrow.isoformat()}T10:00"
    tomorrow_1100 = f"{tomorrow.isoformat()}T11:00"
    calendar_calls: list[tuple[str, str, str, str]] = []
    monkeypatch.setattr(
        "apps.shell.agent_runtime.get_model_profile_service",
        lambda: SimpleNamespace(
            get_defaults=lambda: {"chat": ""},
            get_profile_private=lambda profile_id: (_ for _ in ()).throw(KeyError(profile_id)),
        ),
    )
    monkeypatch.setattr(
        "apps.shell.agent_runtime.openai_compatible_chat_message",
        lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("direct calendar event task should not call model")
        ),
    )

    def fake_calendar_create_event(
        title: str,
        *,
        start_at: str,
        end_at: str | None = None,
        calendar_name: str = "",
    ) -> dict:
        calendar_calls.append((title, start_at, str(end_at or ""), calendar_name))
        return {
            "ok": True,
            "action": "calendar.create_event",
            "summary": "Created calendar event",
            "data": {
                "title": title,
                "start_at": start_at,
                "end_at": str(end_at or ""),
                "calendar_name": calendar_name,
            },
        }

    monkeypatch.setattr(
        "apps.shell.agent.tools.desktop.calendar_create_event",
        fake_calendar_create_event,
    )
    try:
        result = _send_foreground_message(api, "明天上午10点日历上加一个开会")
        task = runtime.state.get_task(result["task_id"])
        link = service.get_task_run_link(result["task_id"])
        run = service.get_run(link["run_id"])
        events = service.list_run_events(run["run_id"], include_internal=True)["events"]
        event_types = [event["event_type"] for event in events]
        planned_event = next(event for event in events if event["event_type"] == "agent.desktop.intent_planned")
        assistant = runtime.chat_session.get_assistant_message_for_task(result["task_id"])

        assert result["ok"] is True
        assert result["status"] == "waiting_approval"
        assert result["run_id"] == run["run_id"]
        assert calendar_calls == []
        assert result["agent_task"]["status"] == "waiting_approval"
        assert result["agent_task"]["needs_user_action"] is True
        assert result["agent_task"]["pending_approvals"][0]["tool_name"] == (
            "calendar.create_event"
        )
        assert result["agent_task"]["tool_calls"][-1]["tool_name"] == "calendar.create_event"
        assert result["agent_task"]["tool_calls"][-1]["status"] == "waiting_approval"
        assert result["agent_task"]["tool_calls"][-1]["input_preview"] == {
            "title": "开会",
            "start_at": tomorrow_1000,
            "end_at": tomorrow_1100,
        }
        assert planned_event["payload"]["tool"] == "calendar.create_event"
        assert task is not None
        assert task.status != TaskStatus.COMPLETED
        assert assistant is not None
        assert assistant.status != MessageStatus.COMPLETED
        assert run["status"] == "approval_required"
        assert run["pending_approval"]["tool"] == "calendar.create_event"
        assert run["pending_approval"]["input_preview"] == {
            "title": "开会",
            "start_at": tomorrow_1000,
            "end_at": tomorrow_1100,
        }
        assert "agent.desktop.intent_planned" in event_types
        assert "agent.tool.call" not in event_types
        assert "agent.desktop.intent_approval_required" in event_types
        assert "agent.desktop.intent_completed" not in event_types
        assert "agent.replan.requested" not in event_types
        assert "model.request.started" not in event_types
        assert "model.requested" not in event_types
    finally:
        service.close()
        store.close()


