def test_send_message_executes_direct_running_apps_task(tmp_path, monkeypatch):
    api, runtime, store = _make_api(tmp_path)
    service = _make_agent_runtime_service(tmp_path)
    runtime.agent_runtime_service = service
    running_calls = 0
    monkeypatch.setattr(
        "apps.shell.agent_runtime.get_model_profile_service",
        lambda: SimpleNamespace(
            get_defaults=lambda: {"chat": ""},
            get_profile_private=lambda profile_id: (_ for _ in ()).throw(KeyError(profile_id)),
        ),
    )
    monkeypatch.setattr(
        "apps.shell.agent_runtime.openai_compatible_chat_message",
        lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("direct running apps task should not call model")
        ),
    )

    def fake_running_apps() -> dict:
        nonlocal running_calls
        running_calls += 1
        return {
            "ok": True,
            "action": "desktop.running_apps",
            "summary": "Running apps: Finder, Google Chrome, Music",
            "data": {
                "apps": [
                    {"name": "Finder", "pid": 101, "frontmost": False},
                    {"name": "Google Chrome", "pid": 202, "frontmost": True},
                    {"name": "Music", "pid": 303, "frontmost": False},
                ],
                "frontmost": "Google Chrome",
            },
        }

    monkeypatch.setattr("apps.shell.agent.tools.desktop.running_apps", fake_running_apps)
    try:
        result = _send_foreground_message(api, "现在开了哪些应用")
        task = runtime.state.get_task(result["task_id"])
        run = service.get_run(result["run_id"])
        event_types = [
            event["event_type"]
            for event in service.list_run_events(run["run_id"], include_internal=True)["events"]
        ]
        assistant = runtime.chat_session.get_assistant_message_for_task(result["task_id"])

        assert result["ok"] is True
        assert result["status"] == "completed"
        assert result["agent_task"]["status"] == "completed"
        assert result["agent_task"]["needs_user_action"] is False
        assert result["agent_task"]["pending_approvals"] == []
        assert result["agent_task"]["summary"] == (
            "正在运行的应用：Finder, Google Chrome, Music。前台是 Google Chrome。"
        )
        assert result["agent_task"]["tool_calls"][-1]["tool_name"] == "desktop.running_apps"
        assert result["agent_task"]["tool_calls"][-1]["status"] == "completed"
        assert task is not None
        assert task.status == TaskStatus.COMPLETED
        assert task.result == "正在运行的应用：Finder, Google Chrome, Music。前台是 Google Chrome。"
        assert assistant is not None
        assert assistant.status == MessageStatus.COMPLETED
        assert assistant.content == "正在运行的应用：Finder, Google Chrome, Music。前台是 Google Chrome。"
        assert running_calls == 1
        assert run["status"] == "completed"
        assert run["pending_approval"] == {}
        assert "agent.desktop.intent_planned" in event_types
        assert "agent.tool.call" in event_types
        assert "agent.desktop.intent_completed" in event_types
        assert "agent.desktop.intent_approval_required" not in event_types
        assert "model.request.started" not in event_types
        assert "model.requested" not in event_types

        result = _send_foreground_message(api, "列一下打开的应用")
        task = runtime.state.get_task(result["task_id"])
        run = service.get_run(result["run_id"])
        event_types = [
            event["event_type"]
            for event in service.list_run_events(run["run_id"], include_internal=True)["events"]
        ]
        assistant = runtime.chat_session.get_assistant_message_for_task(result["task_id"])

        assert result["ok"] is True
        assert result["status"] == "completed"
        assert result["agent_task"]["status"] == "completed"
        assert result["agent_task"]["summary"] == (
            "正在运行的应用：Finder, Google Chrome, Music。前台是 Google Chrome。"
        )
        assert result["agent_task"]["tool_calls"][-1]["tool_name"] == "desktop.running_apps"
        assert task is not None
        assert task.status == TaskStatus.COMPLETED
        assert assistant is not None
        assert assistant.status == MessageStatus.COMPLETED
        assert assistant.content == "正在运行的应用：Finder, Google Chrome, Music。前台是 Google Chrome。"
        assert running_calls == 2
        assert run["status"] == "completed"
        assert "agent.desktop.intent_planned" in event_types
        assert "agent.tool.call" in event_types
        assert "agent.desktop.intent_completed" in event_types
        assert "model.request.started" not in event_types
        assert "model.requested" not in event_types
    finally:
        service.close()
        store.close()


def test_send_message_executes_direct_active_window_task(tmp_path, monkeypatch):
    api, runtime, store = _make_api(tmp_path)
    service = _make_agent_runtime_service(tmp_path)
    runtime.agent_runtime_service = service
    active_window_calls = 0
    monkeypatch.setattr(
        "apps.shell.agent_runtime.get_model_profile_service",
        lambda: SimpleNamespace(
            get_defaults=lambda: {"chat": ""},
            get_profile_private=lambda profile_id: (_ for _ in ()).throw(KeyError(profile_id)),
        ),
    )
    monkeypatch.setattr(
        "apps.shell.agent_runtime.openai_compatible_chat_message",
        lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("direct active window task should not call model")
        ),
    )

    def fake_active_window() -> dict:
        nonlocal active_window_calls
        active_window_calls += 1
        return {
            "ok": True,
            "action": "desktop.active_window",
            "summary": "Foreground window: Google Chrome - ChatGPT",
            "data": {
                "app_name": "Google Chrome",
                "title": "ChatGPT",
                "pid": 202,
            },
        }

    monkeypatch.setattr("apps.shell.agent.tools.desktop.active_window", fake_active_window)
    try:
        prompts = (
            "现在用的是哪个 App",
            "现在前台是什么",
            "我正在用什么应用",
            "现在前台是不是 Chrome",
            "is Chrome frontmost",
        )
        for prompt in prompts:
            result = _send_foreground_message(api, prompt)
            task = runtime.state.get_task(result["task_id"])
            run = service.get_run(result["run_id"])
            event_types = [
                event["event_type"]
                for event in service.list_run_events(run["run_id"], include_internal=True)["events"]
            ]
            assistant = runtime.chat_session.get_assistant_message_for_task(result["task_id"])

            assert result["ok"] is True
            assert result["status"] == "completed"
            assert result["agent_task"]["status"] == "completed"
            assert result["agent_task"]["needs_user_action"] is False
            assert result["agent_task"]["pending_approvals"] == []
            assert result["agent_task"]["summary"] == "当前前台窗口是 Google Chrome：ChatGPT。"
            assert result["agent_task"]["tool_calls"][-1]["tool_name"] == "desktop.active_window"
            assert result["agent_task"]["tool_calls"][-1]["status"] == "completed"
            assert task is not None
            assert task.status == TaskStatus.COMPLETED
            assert task.result == "当前前台窗口是 Google Chrome：ChatGPT。"
            assert assistant is not None
            assert assistant.status == MessageStatus.COMPLETED
            assert assistant.content == "当前前台窗口是 Google Chrome：ChatGPT。"
            assert run["status"] == "completed"
            assert run["pending_approval"] == {}
            assert "agent.desktop.intent_planned" in event_types
            assert "agent.tool.call" in event_types
            assert "agent.desktop.intent_completed" in event_types
            assert "agent.desktop.intent_approval_required" not in event_types
            assert "model.request.started" not in event_types
            assert "model.requested" not in event_types

        assert active_window_calls == len(prompts)
    finally:
        service.close()
        store.close()


def test_send_message_executes_direct_windows_list_task(tmp_path, monkeypatch):
    api, runtime, store = _make_api(tmp_path)
    service = _make_agent_runtime_service(tmp_path)
    runtime.agent_runtime_service = service
    windows_calls: list[str] = []
    monkeypatch.setattr(
        "apps.shell.agent_runtime.get_model_profile_service",
        lambda: SimpleNamespace(
            get_defaults=lambda: {"chat": ""},
            get_profile_private=lambda profile_id: (_ for _ in ()).throw(KeyError(profile_id)),
        ),
    )
    monkeypatch.setattr(
        "apps.shell.agent_runtime.openai_compatible_chat_message",
        lambda *_args, **_kwargs: (_ for _ in ()).throw(
            AssertionError("direct windows list task should not call model")
        ),
    )

    def fake_windows(app_name: str = "") -> dict:
        windows_calls.append(app_name)
        return {
            "ok": True,
            "action": "desktop.windows",
            "summary": "Read open windows",
            "data": {
                "app_name": app_name,
                "windows": [
                    {"app_name": "Google Chrome", "title": "ChatGPT"},
                    {"app_name": "Finder", "title": "Downloads"},
                ],
            },
        }

    monkeypatch.setattr("apps.shell.agent.tools.desktop.windows", fake_windows)
    try:
        result = _send_foreground_message(api, "看看打开了哪些窗口")
        task = runtime.state.get_task(result["task_id"])
        run = service.get_run(result["run_id"])
        event_types = [
            event["event_type"]
            for event in service.list_run_events(run["run_id"], include_internal=True)["events"]
        ]
        assistant = runtime.chat_session.get_assistant_message_for_task(result["task_id"])

        assert result["ok"] is True
        assert result["status"] == "completed"
        assert result["agent_task"]["summary"] == "当前窗口：Google Chrome: ChatGPT; Finder: Downloads。"
        assert result["agent_task"]["tool_calls"][-1]["tool_name"] == "desktop.windows"
        assert result["agent_task"]["tool_calls"][-1]["input_preview"] == {}
        assert result["agent_task"]["tool_calls"][-1]["status"] == "completed"
        assert task is not None
        assert task.status == TaskStatus.COMPLETED
        assert task.result == "当前窗口：Google Chrome: ChatGPT; Finder: Downloads。"
        assert assistant is not None
        assert assistant.status == MessageStatus.COMPLETED
        assert assistant.content == "当前窗口：Google Chrome: ChatGPT; Finder: Downloads。"
        assert windows_calls == [""]
        assert run["status"] == "completed"
        assert "agent.desktop.intent_planned" in event_types
        assert "agent.tool.call" in event_types
        assert "agent.desktop.intent_completed" in event_types
        assert "model.request.started" not in event_types
        assert "model.requested" not in event_types

        filtered = _send_foreground_message(api, "列出Chrome窗口")
        filtered_task = runtime.state.get_task(filtered["task_id"])
        filtered_run = service.get_run(filtered["run_id"])
        filtered_assistant = runtime.chat_session.get_assistant_message_for_task(
            filtered["task_id"]
        )

        assert filtered["ok"] is True
        assert filtered["status"] == "completed"
        assert filtered["agent_task"]["summary"] == "当前窗口：Google Chrome: ChatGPT; Finder: Downloads。"
        assert filtered["agent_task"]["tool_calls"][-1]["tool_name"] == "desktop.windows"
        assert filtered["agent_task"]["tool_calls"][-1]["input_preview"] == {
            "app_name": "Google Chrome"
        }
        assert filtered_task is not None
        assert filtered_task.status == TaskStatus.COMPLETED
        assert filtered_task.result == "当前窗口：Google Chrome: ChatGPT; Finder: Downloads。"
        assert filtered_assistant is not None
        assert filtered_assistant.status == MessageStatus.COMPLETED
        assert filtered_assistant.content == "当前窗口：Google Chrome: ChatGPT; Finder: Downloads。"
        assert windows_calls == ["", "Google Chrome"]
        assert filtered_run["status"] == "completed"
    finally:
        service.close()
        store.close()


